Here's a clean implementation using ASP.NET Core's built-in Problem Details support plus a custom exception-handling middleware:

**1. Register Problem Details services in `Program.cs`:**

```csharp
builder.Services.AddProblemDetails();
```

**2. Create the exception-handling middleware:**

```csharp
// ExceptionHandlingMiddleware.cs
using Microsoft.AspNetCore.Mvc;

public class ExceptionHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IProblemDetailsService _problemDetailsService;
    private readonly ILogger<ExceptionHandlingMiddleware> _logger;

    public ExceptionHandlingMiddleware(
        RequestDelegate next,
        IProblemDetailsService problemDetailsService,
        ILogger<ExceptionHandlingMiddleware> logger)
    {
        _next = next;
        _problemDetailsService = problemDetailsService;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unhandled exception occurred");
            await HandleExceptionAsync(context, ex);
        }
    }

    private async Task HandleExceptionAsync(HttpContext context, Exception exception)
    {
        var problemDetails = exception switch
        {
            KeyNotFoundException ex => new ProblemDetails
            {
                Status = StatusCodes.Status404NotFound,
                Title = "Resource Not Found",
                Detail = ex.Message
            },
            ArgumentException ex => new ProblemDetails
            {
                Status = StatusCodes.Status400BadRequest,
                Title = "Bad Request",
                Detail = ex.Message
            },
            InvalidOperationException ex => new ProblemDetails
            {
                Status = StatusCodes.Status409Conflict,
                Title = "Conflict",
                Detail = ex.Message
            },
            _ => new ProblemDetails
            {
                Status = StatusCodes.Status500InternalServerError,
                Title = "Internal Server Error",
                Detail = "An unexpected error occurred"  // no sensitive details
            }
        };

        context.Response.StatusCode = problemDetails.Status!.Value;

        await _problemDetailsService.WriteAsync(new ProblemDetailsContext
        {
            HttpContext = context,
            ProblemDetails = problemDetails
        });
    }
}
```

**3. Wire it up in `Program.cs`:**

```csharp
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddProblemDetails();

var app = builder.Build();
app.UseMiddleware<ExceptionHandlingMiddleware>();

// Your endpoints — no try-catch needed
app.MapGet("/items/{id}", (int id) =>
{
    if (id < 0) throw new ArgumentException("ID must be positive");
    if (id == 0) throw new KeyNotFoundException("Item not found");
    if (id == 99) throw new InvalidOperationException("Item is locked");
    return Results.Ok(new { Id = id, Name = "Widget" });
});

app.Run();
```

**Example 404 response:**

```json
{
  "type": "https://tools.ietf.org/html/rfc9110#section-15.5.5",
  "title": "Resource Not Found",
  "status": 404,
  "detail": "Item not found"
}
```

**Key points:**
- `AddProblemDetails()` + `IProblemDetailsService` handles RFC 7807 serialization and content negotiation automatically
- The middleware catches all exceptions globally — no per-endpoint try-catch
- Unhandled exceptions return a generic message, hiding stack traces and internals
- The `switch` expression makes it easy to add more exception-to-status mappings
